"""Weekly timesheet summary for the design studio."""
from collections import defaultdict


def parse_line(line):
    """'2024-03-04,client-a,5400' -> (day, project, seconds)"""
    day, project, seconds = line.strip().split(",")
    return day, project, int(seconds)


def totals(lines):
    """Seconds logged per project."""
    out = defaultdict(int)
    for line in lines:
        if line.strip():
            _, project, seconds = parse_line(line)
            out[project] += seconds
    return dict(out)


def fmt_duration(seconds):
    """How a duration is shown in the summary."""
    return str(seconds)


def summary(lines):
    rows = sorted(totals(lines).items())
    return [f"{project}: {fmt_duration(secs)}" for project, secs in rows]

